import{_ as t}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as r,a as s,b as n,c as l,d as i,e as u,f as p,g as c,h as m,i as d,j as h,k as g}from"./chunks/M-S-SW-BJe4.xYg88VDv.js";import{_ as e}from"./chunks/ON.DXVlsWbj.js";import{_ as o}from"./chunks/OFF.BrU7kQE-.js";import{_ as v}from"./chunks/EN.P9aPnFBv.js";import{_ as b,o as y,c as f,a3 as z}from"./chunks/framework.g9mfNVRQ.js";const R=JSON.parse('{"title":"Montre BlueJay","description":"","frontmatter":{"source_hash":"498f98f131","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/smartwatch/bluejay.md","filePath":"fr/smartwatch/bluejay.md"}'),x={name:"fr/smartwatch/bluejay.md"};function _(q,a,S,D,B,k){return y(),f("div",null,[...a[0]||(a[0]=[z('<div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options montre intelligente<br>   BlueJay Watch</p></div><p>Vous pouvez acheter votre montre BlueJay <a href="https://bluejay.website/" target="_blank" rel="noreferrer">ici : <img src="'+r+'" style="zoom:100%;"></a></p><p>La <a href="https://bluejay.website/shop" target="_blank" rel="noreferrer">BlueJay U3</a> est la montre actuelle, disponible dès maintenant. Elle fait tourner le paquet xDrip complet sous Android et se connecte directement à vos capteurs G6, G7 et Dexcom ONE/ONE+.</p><p>Les modèles plus anciens X2, GTS, U1 et U2 <strong>ne sont plus vendus</strong>. Leurs instructions de configuration sont conservées ci-dessous pour leurs propriétaires.<br> Références des anciens modèles : <a href="https://bluejay.website/shop/product/bluejay-gts-26" target="_blank" rel="noreferrer">GTS</a> (autonome ou avec xDrip), <a href="https://bluejay.website/shop/product/bluejay-u1-27" target="_blank" rel="noreferrer">U1</a> et <a href="https://bluejay.website/shop/product/bluejay-u2-28" target="_blank" rel="noreferrer">U2</a>.</p><div class="info custom-block"><p class="custom-block-title">Partage de la glycémie</p><p>Les BlueJay X2/GTS fonctionnent uniquement en Bluetooth et ne peuvent pas partager les données de glycémie sans être connectées à xDrip sur votre téléphone.<br> Les U1/U2/U3 font tourner xDrip complet et peuvent aussi relayer les valeurs vers un téléphone ou d&#39;autres abonnés via Bluetooth (xDrip Link) ou Internet (xDrip Sync).</p></div><p>Les montres BlueJay sont de puissants compagnons pour vos capteurs G6, G7 et 1/1+. Elles se connectent directement à l&#39;émetteur, mais vous devez connaître leurs limites.</p><h5 id="g6g7-and-11" tabindex="-1">G6/G7 et 1/1+ <a class="header-anchor" href="#g6g7-and-11" aria-label="Permalink to &quot;G6/G7 et 1/1+ {#g6g7-and-11}&quot;">​</a></h5><p>Ces émetteurs ont deux emplacements Bluetooth : téléphone et non-téléphone.<br> Vous pouvez configurer vos emplacements selon le tableau ci-dessous. Seuls deux appareils peuvent être connectés simultanément à l&#39;émetteur, chacun utilisant son propre emplacement.<br> Par défaut, BlueJay utilise l&#39;emplacement non-téléphone. Voir <a href="#run-collector">ici pour la GTS</a> comment modifier ce paramètre.</p><p>Les U1, U2 et U3 doivent être connectées en premier au capteur. Une fois connectées, vous pouvez aussi activer la seconde connexion et la montre choisira automatiquement l&#39;emplacement libre.</p><table tabindex="0"><thead><tr><th>Application du fabricant</th><th>Récepteur</th><th>Pompe connectée</th><th>Montre BlueJay</th></tr></thead><tbody><tr><td>Inutilisable</td><td>Inutilisable</td><td>Inutilisable</td><td>Emplacement non-téléphone <strong>xDrip utilise l&#39;emplacement téléphone</strong></td></tr><tr><td><strong>Utilise l&#39;emplacement téléphone</strong></td><td>Inutilisable</td><td>Inutilisable</td><td>Emplacement non-téléphone</td></tr><tr><td>Inutilisable</td><td><strong>Utilise l&#39;emplacement non-téléphone</strong></td><td>Inutilisable</td><td>Emplacement téléphone</td></tr><tr><td>Inutilisable</td><td>Inutilisable</td><td>t:slim, Omnipod 5 <strong>utilisent les emplacements non-téléphone</strong></td><td>Emplacement téléphone</td></tr><tr><td>Inutilisable</td><td>Inutilisable</td><td>CamAPS, DBLG1 <strong>utilisent l&#39;emplacement téléphone</strong></td><td>Emplacement non-téléphone</td></tr></tbody></table><p><em>Remarque : xDrip utilise l&#39;emplacement téléphone par défaut ; l&#39;emplacement non-téléphone nécessite le mode Engineering</em></p><h2 id="bluejay-u3" tabindex="-1">BlueJay U3 <a class="header-anchor" href="#bluejay-u3" aria-label="Permalink to &quot;BlueJay U3 {#bluejay-u3}&quot;">​</a></h2><p>La U3 fait tourner Android complet et le cœur de xDrip directement sur la montre. Vous la configurez sur la montre et pouvez, si vous le souhaitez, relayer les valeurs vers votre téléphone.</p><h3 id="u3-controls" tabindex="-1">Commandes de la U3 <a class="header-anchor" href="#u3-controls" aria-label="Permalink to &quot;Commandes de la U3 {#u3-controls}&quot;">​</a></h3><p>La U3 a deux boutons physiques : un bouton <strong>Gauche</strong> (orange) et un bouton <strong>Droit</strong>. Sur les U1/U2, la commande de droite était une molette ; sur la U3, cet emplacement est occupé par l&#39;appareil photo.</p><ul><li>Appuyez sur l&#39;un des boutons pour allumer l&#39;écran.</li><li>Le bouton <strong>Droit</strong> éteint l&#39;écran.</li><li>Le bouton <strong>Gauche</strong> sert de retour.</li><li>Faites un appui long sur le bouton d&#39;alimentation pour afficher le menu Arrêt / Redémarrage / SOS, puis faites glisser l&#39;option voulue vers la droite.</li></ul><h3 id="get-readings-on-the-u3" tabindex="-1">Recevoir les valeurs sur la U3 <a class="header-anchor" href="#get-readings-on-the-u3" aria-label="Permalink to &quot;Recevoir les valeurs sur la U3 {#get-readings-on-the-u3}&quot;">​</a></h3><p>Saisissez l&#39;identifiant du capteur dans xDrip sur la montre, exactement comme sur un téléphone : allez dans Paramètres  ›  Source de données matérielle  ›  DexcomG5/G6/G7.</p><ul><li><strong>G6</strong> : saisissez l&#39;<strong>ID de l&#39;émetteur (TXID)</strong>.</li><li><strong>G7 / Dexcom ONE+</strong> : saisissez le <strong>code d&#39;appairage à 4 chiffres</strong>.</li></ul><p>Avec un nouveau capteur, saisissez d&#39;abord l&#39;ID ou le code sur la montre et laissez-la recevoir des valeurs avant de le saisir dans une application de téléphone. Avec un capteur déjà en cours d&#39;utilisation et connecté à une application de téléphone, désactivez temporairement cette application (fermez-la, désactivez le Bluetooth ou éloignez-vous), connectez la montre, puis réactivez l&#39;application du téléphone une fois que la montre reçoit des valeurs.</p><h3 id="transmitter-slot" tabindex="-1">Emplacement de l&#39;émetteur <a class="header-anchor" href="#transmitter-slot" aria-label="Permalink to &quot;Emplacement de l&#39;émetteur {#transmitter-slot}&quot;">​</a></h3><p>Par défaut, la U3 utilise l&#39;<strong>emplacement non-téléphone</strong>. Consultez le <a href="#g6g7-and-11">tableau des emplacements ci-dessus</a> pour choisir le bon emplacement. Pour passer la montre sur l&#39;<strong>emplacement téléphone</strong>, scannez le QR code correspondant dans :</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Configuration automatique</p></div><p>Évitez de changer à répétition l&#39;appareil associé à un emplacement : le capteur peut se bloquer. L&#39;emplacement est une configuration fixe, pas un échange à chaud.</p><div class="warning custom-block"><p class="custom-block-title">Mise à jour canal téléphone pour le G7</p><p>Si votre montre ne reçoit plus les valeurs du <strong>G7</strong>, appliquez la mise à jour logicielle de la montre : sur la montre, ouvrez <strong>Paramètres Android › Software Upgrade</strong>, en étant connecté au Wi-Fi et en charge (batterie &gt; 25 %), recherchez les mises à jour et installez-les.<br> Vous pouvez ensuite passer la montre sur le canal téléphone en scannant le QR code affiché dans xDrip <strong>Paramètres › Configuration automatique</strong>, puis redémarrer la montre.<br> Avec cette méthode, la <strong>montre et une application de téléphone ne peuvent pas toutes les deux</strong> recevoir directement les valeurs du capteur : désactivez le collecteur de l&#39;application du téléphone si la montre est le collecteur.</p></div><h3 id="snooze-an-xdrip-alarm" tabindex="-1">Mettre en veille une alarme xDrip <a class="header-anchor" href="#snooze-an-xdrip-alarm" aria-label="Permalink to &quot;Mettre en veille une alarme xDrip {#snooze-an-xdrip-alarm}&quot;">​</a></h3><p>Faites un appui long sur le <strong>bouton Gauche orange</strong> jusqu&#39;à ce que la montre vibre.</p><h3 id="relay-readings-to-your-phone-or-followers" tabindex="-1">Relayer les valeurs vers votre téléphone ou vos abonnés <a class="header-anchor" href="#relay-readings-to-your-phone-or-followers" aria-label="Permalink to &quot;Relayer les valeurs vers votre téléphone ou vos abonnés {#relay-readings-to-your-phone-or-followers}&quot;">​</a></h3><p>Lorsque la montre est le collecteur, vous pouvez quand même alimenter votre téléphone et d&#39;autres appareils :</p><ul><li><strong>xDrip Link</strong> : montre ↔ téléphone via Bluetooth lorsqu&#39;ils sont à portée. Sur la montre, ouvrez l&#39;application <strong>xDrip Link</strong>, activez-la et scannez son QR code dans xDrip sur le téléphone <strong>Paramètres › Configuration automatique</strong>. Les paramètres BlueJay saisis sur le téléphone (y compris le TXID ou le code d&#39;appairage) sont copiés sur la montre. Si le téléphone ne doit pas collecter directement, réglez <a href="#run-phone-collector">Run Phone Collector</a> sur <strong>Off</strong> sur le téléphone.</li><li><strong>xDrip Sync</strong> : relaie les valeurs via Internet (Wi-Fi/4G) d&#39;un appareil principal vers un ou plusieurs abonnés, y compris de montre à montre et de téléphone à montre.</li></ul><div class="info custom-block"><p class="custom-block-title">Fonctions de la montre hors xDrip</p><p>L&#39;insertion d&#39;une carte SIM, le Wi-Fi, l&#39;appareil photo, les cadrans, les bracelets, les protections d&#39;écran, le compte Google, les appels téléphoniques, le GPS, les appels SOS, la musique et la mise à jour logicielle de la montre sont documentés par le fabricant. Consultez la <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">FAQ / Top Tips</a> de BlueJay.</p></div><h2 id="legacy-models-x2-gts" tabindex="-1">Anciens modèles : X2 / GTS <a class="header-anchor" href="#legacy-models-x2-gts" aria-label="Permalink to &quot;Anciens modèles : X2 / GTS {#legacy-models-x2-gts}&quot;">​</a></h2><p>Les étapes suivantes s&#39;appliquent aux anciennes montres X2 et GTS, qui ne sont plus vendues.</p><h3 id="pair-your-watch-to-xdrip-x2-and-gts" tabindex="-1">Appairer votre montre avec xDrip (X2 et GTS) <a class="header-anchor" href="#pair-your-watch-to-xdrip-x2-and-gts" aria-label="Permalink to &quot;Appairer votre montre avec xDrip (X2 et GTS) {#pair-your-watch-to-xdrip-x2-and-gts}&quot;">​</a></h3><p>1 - Assurez-vous que la montre est chargée avant de commencer.</p><p>2 - Activez BlueJay et désactivez le collecteur de la montre.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>3 - Si vous avez une BlueJay GTS, passez à l&#39;étape 6.<br> Si vous avez une BlueJay X2, elle devrait afficher un QR code à l&#39;écran.<br><img src="'+s+'" style="zoom:40%;"><br> Si vous le voyez, passez à l&#39;étape 7.</p><p>4 - Lancez BlueJay Panel et lancez la recherche (Scan).</p><div class="admonition xdripitem"><p class="admonition-title">Launch BlueJay Panel</p></div><img src="'+n+'" style="zoom:76%;"> Lorsque la montre est détectée, vous devriez voir son adresse Mac. Sélectionnez-la. <img src="'+l+'" style="zoom:66%;"><br> Si xDrip ne trouve pas la montre, redémarrez votre téléphone et réessayez. Si vous ne la trouvez toujours pas, vous pouvez saisir manuellement l&#39;adresse Mac de la montre ici <div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p><p> BlueJay Mac</p></div><p>Le QR code devrait maintenant apparaître sur la montre ; si vous le voyez, passez à l&#39;étape 7.</p><p>5 - Si le QR code ne s&#39;affiche pas sur votre montre, sélectionnez QR et réessayez.<br><img src="'+i+'" style="zoom:76%;"><br> Si vous ne voyez toujours pas le QR code, essayez REBOOT, puis <a href="https://bluejay.website/contactus" target="_blank" rel="noreferrer">contactez</a> le fabricant pour obtenir de l&#39;aide ou demandez de l&#39;aide <a href="https://gitter.im/jamorham/BlueJay" target="_blank" rel="noreferrer">ici</a>.</p><p>6 - Sur la GTS, suivez cette séquence de menus pour afficher le QR code :<br> Settings Menu -&gt; Admin Menu -&gt; Show QR Code<br><img src="'+u+'" style="zoom:76%;"></p><p>7 - Dans xDrip, scannez le QR code de la montre</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+t+'" style="zoom:75%;"></p><p> Configuration automatique</p></div><p>Vous devez autoriser xDrip à accéder à l&#39;appareil photo du téléphone.<br> Scannez le QR code affiché sur la montre.<br><img src="'+p+'" style="zoom:50%;"></p><p>Configurez la montre en abonné : vous devriez voir votre glycémie en quelques minutes.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Send Readings <span class="symbol"><img src="'+v+'" style="zoom:75%;"></span></p></div><p>Vérifiez dans <a href="./../troubleshoot/systemstatus.html">État du système</a> que la montre est bien appairée. Faites glisser jusqu&#39;à l&#39;onglet d&#39;état avancé BlueJay.</p><img src="'+c+'" style="zoom:66%;"><p>Si le cœur de xDrip (xDrip Core) n&#39;est pas installé, installez-le maintenant.</p><h3 id="install-the-xdrip-core" tabindex="-1">Installer le cœur xDrip (xDrip Core) <a class="header-anchor" href="#install-the-xdrip-core" aria-label="Permalink to &quot;Installer le cœur xDrip (xDrip Core) {#install-the-xdrip-core}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Mettez la montre en charge pendant l&#39;installation du cœur</p></div><p>Dans État du système de xDrip, onglet d&#39;état avancé BlueJay, appuyez sur la ligne rouge xDrip Core: Not Installed.</p><img src="'+m+'" style="zoom:71%;"><p>Sélectionnez OK pour mettre à jour la montre.</p><img src="'+d+'" style="zoom:79%;"><p>Vérifiez ensuite État du système : le cœur devrait apparaître comme installé.</p><img src="'+h+'" style="zoom:66%;"><h3 id="run-collector" tabindex="-1">Run collector <a class="header-anchor" href="#run-collector" aria-label="Permalink to &quot;Run collector {#run-collector}&quot;">​</a></h3><p>Run collector signifie que vous utiliserez la montre sans forcément avoir votre téléphone avec vous.</p><p>Si vous utilisez un modèle X2, vous devez configurer la montre avec xDrip.<br> Pour la GTS, vous pouvez le faire directement via le <a href="https://bluejay.website/gts-menu-top" target="_blank" rel="noreferrer">menu</a> de la montre, sans utiliser xDrip.</p><p>Pour utiliser la montre avec xDrip, un émetteur doit être directement connecté à xDrip, avec des données de glycémie actuellement affichées dans xDrip.</p><p>Définissez quel emplacement se connectera à l&#39;émetteur. Consultez le tableau <a href="#g6g7-and-11">ci-dessus</a> pour configurer vos emplacements.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Advanced Settings</p></div><h5 id="run-phone-collector" tabindex="-1">Run Phone Collector <a class="header-anchor" href="#run-phone-collector" aria-label="Permalink to &quot;Run Phone Collector {#run-phone-collector}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Run Phone Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Also run the standard collector on this phone. Only turn this off if you don&#39;t want this phone itself to be connecting to the transmitter.</p></div><p>Active ou désactive la connexion de xDrip à l&#39;émetteur (via l&#39;emplacement téléphone).</p><h5 id="bluejay-uses-phone-slot" tabindex="-1">BlueJay uses Phone Slot <a class="header-anchor" href="#bluejay-uses-phone-slot" aria-label="Permalink to &quot;BlueJay uses Phone Slot {#bluejay-uses-phone-slot}&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">BlueJay uses Phone Slot <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> This allows the BlueJay to occupy the phone slot on the transmitter. Select this if you want another non-phone device to be able to connect to the transmitter and you are not using a phone to connect to the transmitter.</p></div><p>Par défaut, BlueJay utilise l&#39;emplacement non-téléphone. Cette option lui permet d&#39;utiliser l&#39;emplacement téléphone, mais vous devez alors désactiver Run Phone Collector ci-dessus.</p><p>Une fois les emplacements configurés, vous pouvez activer la montre comme collecteur autonome.</p><div class="admonition xdripitem"><p class="admonition-title">BlueJay Watch <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Run Collector <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p></div><p>Vous verrez alors que xDrip sur votre téléphone n&#39;est plus connecté à l&#39;émetteur : c&#39;est BlueJay qui l&#39;est.<br> Lorsque votre montre est à portée Bluetooth, votre téléphone devrait recevoir la glycémie depuis BlueJay.</p><img src="'+g+'" style="zoom:66%;"><h2 id="bluejay-gts" tabindex="-1">BlueJay GTS <a class="header-anchor" href="#bluejay-gts" aria-label="Permalink to &quot;BlueJay GTS {#bluejay-gts}&quot;">​</a></h2><p>La GTS n&#39;a pas besoin de xDrip pour être configurée, mais les étapes ci-dessus s&#39;appliquent aussi si vous souhaitez le faire.</p><p>Regardez la vidéo <a href="https://www.youtube.com/watch?v=JM5cw-xVAZk" target="_blank" rel="noreferrer">ici</a> pour une visite guidée.</p><p>Voyez ici <a href="https://www.youtube.com/watch?v=6YpjuZe2c_Q" target="_blank" rel="noreferrer">comment</a> vous connecter à l&#39;émetteur.</p><h2 id="bluejay-u1u2-legacy" tabindex="-1">BlueJay U1/U2 (anciens modèles) <a class="header-anchor" href="#bluejay-u1u2-legacy" aria-label="Permalink to &quot;BlueJay U1/U2 (anciens modèles) {#bluejay-u1u2-legacy}&quot;">​</a></h2><p>Les U1 et U2 ne sont plus vendues mais font tourner le même paquet xDrip complet que la U3 : la <a href="#bluejay-u3">configuration de la U3</a> ci-dessus s&#39;applique donc. Consultez la <a href="https://bluejay.website/faq" target="_blank" rel="noreferrer">FAQ / Top Tips</a> du fabricant pour des astuces sur les montres de la série U.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2024.11.26" target="_blank" rel="noreferrer"><em>Dernière modification le 18/7/2026</em></a></p>',93)])])}const C=b(x,[["render",_]]);export{R as __pageData,C as default};
